package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil on zero width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil on negative width",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty input returns empty slice",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace-only input returns empty slice",
			text:  "   \t\n  ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:    []string{"hello"},
		},
		{
			name:  "single word too long for width",
			text:  "supercalifragilistic",
			width: 5,
			want:  []string{"supercalifragilistic"},
		},
		{
			name:  "multiple words wrap at spaces",
			text:  "hello world foo bar",
			width: 10,
			want:    []string{"hello", "world foo", "bar"},
		},
		{
			name:  "collapse runs of whitespace",
			text:  "a   b\t\nc",
			width: 10,
			want:    []string{"a b c"},
		},
		{
			name:  "no leading or trailing spaces on lines",
			text:  "  hello   world  ",
			width: 10,
			want:    []string{"hello world"},
		},
		{
			name:  "long word forces own line",
			text:  "short supercalifragilisticexpialidocious longer",
			width: 10,
			want:    []string{"short", "supercalifragilisticexpialidocious", "longer"},
		},
		{
			name:  "exact fit",
			text:  "hello world",
			width: 11,
			want:    []string{"hello world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want == nil {
				return
			}
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v; want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

